import{_ as a,a0 as i,w as s,s as p,ao as u,I as o,x as t,a1 as r,A as l}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const M=JSON.parse('{"title":"AMD 的开源图形驱动程序 Vulkan 现在支持光线追踪 | LCTT x X-CMD","titleTemplate":false,"description":"AMD 的开源图形驱动程序 Vulkan 现在支持光线追踪 | LCTT (202209) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"AMD 的开源图形驱动程序 Vulkan 现在支持光线追踪 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"AMD 的开源图形驱动程序 Vulkan 现在支持光线追踪 | LCTT (202209) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202209/20220919 AMD-s Open Source Vulkan Graphics Drivers Now Enable Ray Tracing","title":"AMD 的开源图形驱动程序 Vulkan 现在支持光线追踪","tag":"202209","desc":""},"relativePath":"202209/20220919 AMD-s Open Source Vulkan Graphics Drivers Now Enable Ray Tracing.md","filePath":"[post].md"}'),d={name:"202209/20220919 AMD-s Open Source Vulkan Graphics Drivers Now Enable Ray Tracing.md"};function D(A,e,T,m,f,V){const n=i("Link");return s(),p("div",null,[e[15]||(e[15]=u('<h1 id="amd-的开源图形驱动程序-vulkan-现在支持光线追踪" tabindex="-1">AMD 的开源图形驱动程序 Vulkan 现在支持光线追踪 <a class="header-anchor" href="#amd-的开源图形驱动程序-vulkan-现在支持光线追踪" aria-label="Permalink to “AMD 的开源图形驱动程序 Vulkan 现在支持光线追踪”">​</a></h1><p><img src="https://www.opensourceforu.com/wp-content/uploads/2022/09/AMD-Ryzen-Zen-CPUs_Next-Gen-1536x842.jpg" alt=""></p><blockquote><p>RDNA 2 GPU 的 Linux 用户可以使用 AMD 的 AMDVLK GPUOpen 开源 Vulkan 驱动程序。</p></blockquote><p>用于 Radeon RX 6000 GPU 的 AMDVLK GPUOpen 图形驱动程序在过去一周改进了对 64 位光线追踪的支持。这涵盖了支持 RDNA 2 图形的 APU 以及桌面/移动 GPU。所有平台上的所有 AMD Vulkan 驱动程序现在都支持硬件光线追踪，包括 Mesa3D RADV、AMDVLK GPUOpen 和 AMDGPU-PRO。</p><p>GPU 光线追踪库（GPURT）的基础是一个 C++ 接口。根据其用法和依赖关系，公共接口被拆分为各种头文件。用户可以在官方的 GitHub 仓库上了解更多信息，它还包括了 RDNA 2 GPURT 的结构细分。最新的 AMDVLK GPUOpen v-2022.Q3.4 信息如下：</p><p><strong>更新和新功能：</strong></p><ul><li>扩展 Navi2x 的 64 位光线追踪功能。</li><li>将 Vulkan 标头升级到版本 1.3.225</li><li>游戏性能优化，包括《荣耀战魂》和《奇点灰烬》</li></ul><p><strong>已解决的问题：</strong></p><ul><li><code>dEQP-VK.api.copy_and_blit.*.resolve_image.whole_copy_before_resolving_transfer.*</code> 新版本 CTS 失败。</li><li>dEQP-VK.pipeline.creation 缓存控件有一个 CTS 警告。</li><li>Ubuntu 22.04 上的 Firefox 损坏</li><li>VulkanInfo 崩溃，管道缓存已停用</li><li>RX 6800 上的 RGP 测试套件故障</li></ul><p>新的改进包括 GPU 光线追踪库（GPURT），它将包括使用 HLSL 之类的着色器在光线追踪中看到的边界体积层次（BVH）的构造和排序处理。这个库将提供一个标准库来改进图形渲染并引入更多的统一性。DirectX 12 DXR 也将与新库一起使用。</p><p>对 GPU 光线追踪（GPURT）库的描述为“一个静态库（源代码交付），为支持 DXR（DirectX 12）和 Vulkan® RT API 的 AMD 驱动程序提供与光线追踪相关的功能。” 该公司的平台抽象库用于构建库（PAL）。</p><p>用户可参考最新 AMDVLK GPUOpen v-2022.Q3.4 升级的安装说明。用户在更新任何软件、硬件或驱动程序之前应备份所有相关数据，以免丢失重要文件。</p><p>为了让最新的 Linux 驱动程序为 AMD、Intel 和 NVIDIA 技术做好准备，已经投入了大量工作，这些技术都是在今年第一季度推出的。</p><hr>',14)),o("p",null,[e[1]||(e[1]=t("via: ",-1)),r(n,{href:"https://www.opensourceforu.com/2022/09/amds-open-source-vulkan-graphics-drivers-now-enable-ray-tracing/"},{default:l(()=>[...e[0]||(e[0]=[t("https://www.opensourceforu.com/2022/09/amds-open-source-vulkan-graphics-drivers-now-enable-ray-tracing/",-1)])]),_:1})]),o("p",null,[e[6]||(e[6]=t("作者：",-1)),r(n,{href:"https://www.opensourceforu.com/author/laveesh-kocher/"},{default:l(()=>[...e[2]||(e[2]=[t("Laveesh Kocher",-1)])]),_:1}),e[7]||(e[7]=t(" 选题：",-1)),r(n,{href:"https://github.com/lkxed"},{default:l(()=>[...e[3]||(e[3]=[t("lkxed",-1)])]),_:1}),e[8]||(e[8]=t(" 译者：",-1)),r(n,{href:"https://github.com/littlebirdnest"},{default:l(()=>[...e[4]||(e[4]=[t("littlebirdnest",-1)])]),_:1}),e[9]||(e[9]=t(" 校对：",-1)),r(n,{href:"https://github.com/wxy"},{default:l(()=>[...e[5]||(e[5]=[t("wxy",-1)])]),_:1})]),o("p",null,[e[12]||(e[12]=t("本文由 ",-1)),r(n,{href:"https://github.com/LCTT/TranslateProject"},{default:l(()=>[...e[10]||(e[10]=[t("LCTT",-1)])]),_:1}),e[13]||(e[13]=t(" 原创编译，",-1)),r(n,{href:"https://linux.cn/"},{default:l(()=>[...e[11]||(e[11]=[t("Linux中国",-1)])]),_:1}),e[14]||(e[14]=t(" 荣誉推出",-1))])])}const g=a(d,[["render",D]]);export{M as __pageData,g as default};
